<script>
const icStore=@json(route('indicator-categories-store')),icUpdate=@json(route('indicator-categories-update','__ID__'));
function openIndicatorCategory(encoded){const form=document.getElementById('indicatorCategoryForm'),data=encoded?JSON.parse(atob(encoded)):{};form.reset();form.action=icStore;indicatorCategoryMethod.innerHTML='';form.elements.name.value=data.name||'';form.elements.description.value=data.description||'';form.elements.status.value=data.status===false||Number(data.status)===0?'0':'1';indicatorCategoryTitle.textContent=encoded?'Edit Performance Indicator Category':'Add New Performance Indicator Category';indicatorCategorySave.textContent=encoded?'Update':'Save';if(encoded){form.action=icUpdate.replace('__ID__',data.id);indicatorCategoryMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}
function showIndicatorCategory(encoded){const data=JSON.parse(atob(encoded)),root=document.getElementById('indicatorCategoryDetailsModal');root.querySelector('[data-ic-detail="name"]').textContent=data.name||'—';root.querySelector('[data-ic-detail="description"]').textContent=data.description||'—';const active=Number(data.status)===1;root.querySelector('[data-ic-detail="status"]').innerHTML='<span class="ic-status '+(active?'':'inactive')+'">'+(active?'Active':'Inactive')+'</span>'}
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.ic-confirm').forEach(function(form){form.addEventListener('submit',function(event){if(form.dataset.ok)return;event.preventDefault();Swal.fire({title:form.dataset.title,text:form.dataset.delete?'This action cannot be undone.':'',icon:'warning',showCancelButton:true,confirmButtonText:form.dataset.delete?'Delete':'Yes, continue',confirmButtonColor:form.dataset.delete?'#f1416c':'#00b783'}).then(function(result){if(result.isConfirmed){form.dataset.ok='1';form.submit()}})})});@if($errors->any())openIndicatorCategory();new bootstrap.Modal(document.getElementById('indicatorCategoryFormModal')).show();@endif});
</script>
